// Mini relais MQTT 3.1.1 (sous-ensemble d'« aedes ») pour les tests hors ligne : CONNECT (testament, identifiants), SUBSCRIBE, PUBLISH QoS 0/1, PING, DISCONNECT.
function Aedes(){const subs=new Set(),B={authorizeForward:null,authenticate:null,clients:subs};
 const str=s=>{const b=Buffer.from(s,'utf8'),h=Buffer.alloc(2);h.writeUInt16BE(b.length);return Buffer.concat([h,b])};
 const pkt=(h,body)=>{let n=body.length;const L=[];do{let d=n%128;n=Math.floor(n/128);if(n)d|=128;L.push(d)}while(n);return Buffer.concat([Buffer.from([h,...L]),body])};
 const match=(f,t)=>{if(f===t||f==='#')return true;const F=f.split('/'),T=t.split('/');for(let i=0;i<F.length;i++){if(F[i]==='#')return true;if(i>=T.length)return false;if(F[i]!=='+'&&F[i]!==T[i])return false}return F.length===T.length};
 const deliver=(from,topic,payload)=>{for(const c of subs){if(!c.on||!c.f.some(f=>match(f,topic)))continue;let pk={topic,payload};if(B.authorizeForward){pk=B.authorizeForward(c,pk);if(!pk)continue}c.w(pkt(0x30,Buffer.concat([str(topic),payload])))}};
 B.handle=st=>{const c={f:[],on:false,will:null,w:b=>{try{st.write(b)}catch(e){}}};let buf=Buffer.alloc(0),gone=false;
  const end=clean=>{if(gone)return;gone=true;subs.delete(c);if(!clean&&c.will&&c.on)deliver(c,c.will.t,c.will.p);c.on=false;try{st.destroy?.()}catch(e){}};
  st.on('data',d=>{buf=Buffer.concat([buf,d]);for(;;){if(buf.length<2)return;let n=0,m=1,i=1,x;do{if(i>=buf.length)return;x=buf[i++];n+=(x&127)*m;m*=128}while(x&128&&i<5);if(buf.length<i+n)return;const h=buf[0],p=buf.subarray(i,i+n);buf=buf.subarray(i+n);const t=h>>4;
   if(t===1){let o=0;const rs=()=>{const l=p.readUInt16BE(o);const s=p.subarray(o+2,o+2+l);o+=2+l;return s};rs();o+=1;const fl=p[o++];o+=2;rs();let wt=null,wm=null,un=null,pw=null;if(fl&4){wt=rs().toString();wm=rs()}if(fl&128)un=rs().toString();if(fl&64)pw=rs();
    const ok=r=>{if(!r){c.w(Buffer.from([0x20,2,0,5]));end(true);return}c.on=true;if(wt)c.will={t:wt,p:wm};subs.add(c);c.w(Buffer.from([0x20,2,0,0]))};if(B.authenticate)B.authenticate(c,un,pw,(e,r)=>ok(!e&&r));else ok(true)}
   else if(t===8){const id=p.subarray(0,2);let o=2;const g=[];while(o<p.length){const l=p.readUInt16BE(o);c.f.push(p.subarray(o+2,o+2+l).toString());o+=2+l+1;g.push(0)}c.w(pkt(0x90,Buffer.concat([id,Buffer.from(g)])))}
   else if(t===10){c.w(Buffer.from([0xB0,2,p[0],p[1]]))}
   else if(t===3){const q=h>>1&3,tl=p.readUInt16BE(0),topic=p.subarray(2,2+tl).toString();let o=2+tl;if(q){c.w(Buffer.from([0x40,2,p[o],p[o+1]]));o+=2}deliver(c,topic,Buffer.from(p.subarray(o)))}
   else if(t===12)c.w(Buffer.from([0xD0,0]));else if(t===14)end(true)}});
  st.on('close',()=>end(false));st.on('error',()=>end(false))};
 B.close=()=>{for(const c of subs)c.on=false;subs.clear()};return B}
module.exports=Aedes;module.exports.Aedes={createBroker:async()=>Aedes()};
